CREATE OR REPLACE SECURE VIEW DP_NERC.OUT_AUDIT_RECORD
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Compliance_Package')
  COMMENT = 'Atomic contracted output for AuditRecord'
AS
SELECT f.AUDIT_RECORD_ID, f.DATE_KEY, f.ACTION_REQUIRED, f.AUDIT_TYPE, f.AUDITOR, f.FINDINGS, f.RISK_RATING, d1.FISCAL_YEAR, d1.FULL_DATE, d1.IS_HOLIDAY, d1.IS_WEEKEND, d1.MONTH_NAME, d1.MONTH_NUMBER, d1.QUARTER
FROM CORE.FCT_AUDIT_RECORD f
LEFT JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY;
